s=\"lb-search__terms\">Results for \"{{ search.terms }}\"</p>{% endif %}\n</section>\n{% schema %}\n{\n  \"name\": \"Search\",\n  \"settings\": [\n    {\n      \"id\": \"placeholder\",\n      \"type\": \"text\",\n      \"label\": \"Placeholder\",\n      \"default\": \"Search products\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Search\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ]\n}\n{% endschema %}","schema":{"name":"Search","tag":"section","settings":[{"type":"text","label":"Placeholder","default":"Search products","id":"placeholder"}],"blocks":[],"presets":[{"name":"Search","settings":{},"blocks":[]}],"enabled_on":{"templates":["*"]},"disabled_on":{"templates":[]}}},"after":{"path":"sections/search-box.liquid","source":"<section class=\"lb-search\" data-section-id=\"{{ section.id }}\">\n  <lb-search data-lb-island=\"search\" data-search-url=\"{{ routes.search_url }}\">\n    <form role=\"search\" method=\"get\" action=\"{{ routes.search_url }}\" data-lb-search-form>\n      <label class=\"lb-sr-only\" for=\"lb-search-input-{{ section.id }}\">Search products</label>\n      <input type=\"search\" name=\"search\" id=\"lb-search-input-{{ section.id }}\" data-lb-search-input placeholder=\"{{ section.settings.placeholder }}\" aria-label=\"Search products\" value=\"{{ search.terms }}\">\n      <button type=\"submit\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line></svg><span class=\"lb-sr-only\">Search</span></button>\n    </form>\n  </lb-search>\n  {% if search.terms %}<p class=\"lb-search__terms\">Results for \"{{ search.terms }}\"</p>{% endif %}\n</section>\n{% schema %}\n{\n  \"name\": \"Search\",\n  \"settings\": [\n    {\n      \"id\": \"placeholder\",\n      \"type\": \"text\",\n      \"label\": \"Placeholder\",\n      \"default\": \"Search products\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Search\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ]\n}\n{% endschema %}","schema":{"name":"Search","tag":"section","settings":[{"type":"text","label":"Placeholder","default":"Search products","id":"placeholder"}],"blocks":[],"presets":[{"name":"Search","settings":{},"blocks":[]}],"enabled_on":{"templates":["*"]},"disabled_on":{"templates":[]}}}}}$coresections$::jsonb;
  original jsonb;
  bundle jsonb;
  entry record;
BEGIN
  SELECT default_template INTO original FROM public.themes
   WHERE slug='letbuyy-core' AND owned_by_site_id IS NULL
     AND NOT COALESCE(is_site_private,false) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unowned canonical Core catalog is unavailable'; END IF;
  bundle := original->'liquidBundle';
  IF bundle#>>'{package,slug}' IS DISTINCT FROM 'letbuyy-core-liquid'
     OR bundle#>>'{renderer,engine}' IS DISTINCT FROM 'liquid' THEN
    RAISE EXCEPTION 'Unexpected Core package or renderer';
  END IF;
  FOR entry IN SELECT key,value FROM jsonb_each(changes) LOOP
    IF bundle#>ARRAY['sections',entry.key] IS DISTINCT FROM entry.value->'before'
       AND bundle#>ARRAY['sections',entry.key] IS DISTINCT FROM entry.value->'after' THEN
      RAISE EXCEPTION 'Unexpected Core catalog section: %',entry.key;
    END IF;
  END LOOP;
  FOR entry IN SELECT key,value FROM jsonb_each(changes) LOOP
    bundle := jsonb_set(bundle,ARRAY['sections',entry.key],entry.value->'after',false);
  END LOOP;
  IF bundle IS DISTINCT FROM original->'liquidBundle' THEN
    UPDATE public.themes SET default_template=jsonb_set(original,'{liquidBundle}',bundle,false),updated_at=NOW()
      WHERE slug='letbuyy-core' AND owned_by_site_id IS NULL AND NOT COALESCE(is_site_private,false);
  END IF;
END
$refresh$;
